// ==================== FINANCIAL STATUS (RECONCILIATION) ====================
import { state } from '../state.js';
import { supabaseClient } from '../db.js';
import { showToast } from '../components/toasts.js';
import { getReconciliationStatus, formatDisplayDate, todayDateStr } from '../utils/budgetCalendar.js';

export function getFinancialStatusPage() {
  return `
    <h1 class="page-title">Financial Status</h1>
    <p style="color: var(--text-secondary); margin-bottom: 16px;">
      Daily reconciliation for <strong>${state.currentTeam?.team_name || 'your team'}</strong>.
      Green = today or yesterday · Orange = 2–3 days · Red = older.
    </p>

    <div class="card">
      <h2>📊 Reconciliation Status</h2>
      <div id="reconStatusBanner" class="dash-alert" style="margin-bottom:16px;">Loading…</div>

      <form id="reconForm" onsubmit="window.recordReconciliation(event)">
        <div class="form-stack">
          <div class="form-grid-row form-grid-row--recon-date">
            <div class="form-group"><label>Reconciliation Date</label><input type="date" id="reconDate" required></div>
          </div>
          <div class="form-group"><label>Notes</label><textarea id="reconNotes" rows="2" placeholder="Optional"></textarea></div>
        </div>
        <button type="submit">Mark Reconciled</button>
      </form>
    </div>

    <div class="card">
      <h2>History</h2>
      <div class="table-container">
        <table>
          <thead>
            <tr><th>Date</th><th>Notes</th><th>Recorded</th></tr>
          </thead>
          <tbody id="reconHistoryList">
            <tr><td colspan="3" class="empty-state">Loading…</td></tr>
          </tbody>
        </table>
      </div>
    </div>
  `;
}

export async function initFinancialStatusPage() {
  const dateInput = document.getElementById('reconDate');
  if (dateInput) dateInput.value = todayDateStr();

  window.recordReconciliation = recordReconciliation;
  await loadReconciliation();
}

async function loadReconciliation() {
  const teamId = state.currentTeam?.team_id;
  const banner = document.getElementById('reconStatusBanner');
  const tbody = document.getElementById('reconHistoryList');
  if (!teamId) return;

  try {
    const { data, error } = await supabaseClient
      .from('daily_reconciliation')
      .select('*')
      .eq('team_id', teamId)
      .eq('is_deleted', false)
      .order('reconciliation_date', { ascending: false })
      .limit(30);

    if (error) throw error;

    const last = data?.[0];
    const status = getReconciliationStatus(last?.reconciliation_date || null);

    if (banner) {
      banner.className = `dash-alert dash-alert--${status.level}`;
      banner.innerHTML = last
        ? `<div class="dash-alert-body"><strong>Last reconciliation: ${formatDisplayDate(last.reconciliation_date)}</strong><span>${status.message}</span></div>`
        : `<div class="dash-alert-body"><strong>Not reconciled</strong><span>Record today's reconciliation below.</span></div>`;
    }

    if (!data?.length) {
      tbody.innerHTML = '<tr><td colspan="3" class="empty-state">No reconciliation records yet.</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(r => `
      <tr>
        <td>${formatDisplayDate(r.reconciliation_date)}</td>
        <td>${r.notes || '—'}</td>
        <td>${new Date(r.created_at).toLocaleString()}</td>
      </tr>
    `).join('');
  } catch (err) {
    console.error('Load reconciliation error:', err);
    if (banner) {
      banner.className = 'dash-alert dash-alert--danger';
      banner.textContent = `Table not ready: ${err.message}. Run the SQL migration first.`;
    }
    if (tbody) {
      tbody.innerHTML = `<tr><td colspan="3" class="empty-state" style="color:#dc3545;">${err.message}</td></tr>`;
    }
  }
}

async function recordReconciliation(e) {
  e.preventDefault();
  const teamId = state.currentTeam?.team_id;
  const reconciliation_date = document.getElementById('reconDate').value;
  const notes = document.getElementById('reconNotes').value.trim() || null;

  try {
    const { error } = await supabaseClient.from('daily_reconciliation').upsert({
      team_id: teamId,
      reconciliation_date,
      notes,
      created_by: state.user?.id,
      is_deleted: false
    }, { onConflict: 'team_id,reconciliation_date' });

    if (error) throw error;
    showToast('Reconciliation recorded', 'success');
    document.getElementById('reconNotes').value = '';
    await loadReconciliation();
  } catch (err) {
    showToast(err.message || 'Failed to save', 'error');
  }
}
